  "stormFootnote": "Строка записывается при изменении состояния или атрибутов сущности. Полностью идентичные обновления Home Assistant не записывает вовсе; «без смены состояния» означает, что основное значение осталось прежним, а изменились только атрибуты. Размер атрибутов оценивается за последние 24 часа. Housekeeper не меняет настройки Recorder: вы можете исключить сущности в конфигурации в разделе recorder или увеличить интервал опроса в самом источнике.",
