  "dbAdvice_growth": "Во вкладке «Нагрузка на Recorder» видно, кто пишет больше всего. Исключите лишние сущности из Recorder или уменьшите срок хранения.",
  "dbAdvice_duplicates": "Housekeeper это не исправляет. Создайте резервную копию и проверьте эти ряды в разделе Панель разработчика → Статистика.",
  "dbAdvice_missing_hours": "Общие пропуски восполнить нельзя: в это время Home Assistant был выключен или не работал Recorder. Индивидуальные пропуски обычно означают, что сама сущность была временно недоступна.",
  "dbAdvice_statistics_issues": "В разделе Панель разработчика → Статистика можно исправить единицу измерения или удалить проблемный ряд. Сначала создайте резервную копию.",
  "dbAdvice_recorder_gap": "Проверьте системный журнал на ошибки Recorder (база заблокирована, диск переполнен) и сохраните резервную копию базы данных.",
  "dbFootnote": "Только чтение. Размер базы данных фиксируется раз в сутки (только само число) для расчёта скорости роста. Пропуском считается интервал не менее {gap} мин. без единой записи состояний за последние {gapDays} дн.; если он совпадает со временем простоя Home Assistant по его собственному журналу, он засчитывается как обычный перезапуск. Пропущенные часы учитываются от {missing} за последние {missingDays} дн. Housekeeper ничего не чинит и не удаляет.",
