  "helpFinding": "Что-то сейчас привлекает внимание, например, сбой устройства, дубликат или отсутствующая ссылка. Каждый объект считается один раз для каждого правила.",
  "helpFollowupsT": "Следствия",
  "helpFollowups": "Когда происходит сбой устройства, за ним следуют его сущности. Они зависят от причины как следствия и не считаются отдельными находками.",
  "helpWatchT": "Наблюдение после обновления системы",
  "helpWatch": "После обновления Home Assistant, операционной системы или Supervisor Housekeeper проводит проверки несколько дополнительных часов и сравнивает с предыдущим состоянием. Он показывает, что перестало работать с тех пор.",
  "helpTogetherT": "В то же время",
  "helpTogether": "Находки, которые начались одновременно с обновлением или перезапуском. Это временнáя связь, а не причина.",
  "helpNAllT": "Все находки",
  "helpNAll": "Находки без их следствий; причина со следствиями считается один раз. Плитки ниже считают так же, с разбивкой по причинам, со следствиями мелким шрифтом рядом.",
  "helpNTrendT": "+n за 5 дней",
  "helpNTrend": "Изменение за последние дни, красное при росте. Линия считает так же, как плитка, без следствий; она начинается заново, потому что в предыдущие дни следствия не разделялись.",
  "helpNTabsT": "Открытые, Известные, Скрытые, Выполненные",
  "helpNTabs": "Находки по статусу: всё ещё нужно сделать, сохранены намеренно, больше не показываются, с тех пор исправлены. «Все по одной» считает каждую находку отдельно, включая следствия; «Причины со следствиями» считает только те причины, у которых есть следствия.",
  "helpNFollowT": "n следствий",
  "helpNFollow": "Находки, которые существуют только потому, что произошел сбой причины. «объясняет n находок» называет те же самые, «затронуто n сущностей» — стоящие за ними сущности.",
  "helpNLevelT": "Серьёзность",
