  "accNoneSys": "Интеграций с системным доступом не найдено.",
  "accNoneCloud": "Обмена данными с внешними сервисами не обнаружено.",
  "accFootnote": "Housekeeper определяет системный доступ и потоки данных по домену интеграции (например, zha → радиомодуль Zigbee, mobile_app → геолокация), а обмен с облаком — также по классу IoT (cloud_polling или cloud_push); наличие сущностей трекеров и камер засчитывается как доступ к геолокации и камерам. Эта классификация — ориентир, а не строгий аудит. Высокий риск: доступ к системе, командной оболочке, радиомодулям, камерам или геолокации. Средний: передача данных во внешнюю сеть или иной специальный доступ. Игнорируемые интеграции пропускаются. Права приложений считываются из Supervisor: высокий риск — полномочия, равносильные root на хосте (полный доступ к железу, привилегированный режим, Docker API, процессы хоста, роль admin или manager в Supervisor); средний — использование сети хоста, доступ к API Home Assistant или проверке логинов, а также отключённый профиль AppArmor. Нажатие на приложение открывает его в Home Assistant. Ничего не меняется и не сохраняется.",
