  "secOpen": "Открыть {name} в Home Assistant",
  "secFootnote": "Housekeeper распознаёт учётные данные по названию поля в настройках интеграции (password, token, api_key, secret, webhook, pin) и проверяет только то, пустое оно или нет. Сами значения, их фрагменты или длина никогда не считываются, не отображаются и не экспортируются. Это ориентировочная проверка: секреты под нестандартными именами полей не будут замечены, а поле с похожим названием может содержать безобидную настройку. Нажатие на строку открывает страницу интеграции в Home Assistant, где можно изменить учётные данные. Ничего не меняется и не сохраняется.",
